import React from "react";
import {
  FaWallet,
  FaArrowUp,
  FaArrowDown,
  FaPiggyBank,
  FaChartPie,
} from "react-icons/fa";

const MonthlySummary = ({
  incomes = [],
  expenses = [],
}) => {

  const totalIncome = incomes.reduce(
    (sum, item) => sum + Number(item.amount || 0),
    0
  );

  const totalExpense = expenses.reduce(
    (sum, item) => sum + Number(item.amount || 0),
    0
  );

  const totalSavings = totalIncome - totalExpense;

  const totalTransactions =
    incomes.length + expenses.length;

  // Highest Expense Category
  const categoryMap = {};

  expenses.forEach((item) => {
    const category = item.category || "Others";

    categoryMap[category] =
      (categoryMap[category] || 0) +
      Number(item.amount || 0);
  });

  let highestCategory = "N/A";
  let highestAmount = 0;

  Object.entries(categoryMap).forEach(
    ([category, amount]) => {
      if (amount > highestAmount) {
        highestAmount = amount;
        highestCategory = category;
      }
    }
  );

  return (
    <div className="bg-slate-800 rounded-xl p-6 shadow-lg">

      <h2 className="text-2xl font-bold text-white mb-6">
        Monthly Summary
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Income */}
        <div className="bg-slate-700 rounded-lg p-5 flex items-center gap-4">
          <FaArrowDown className="text-green-400 text-3xl"/>

          <div>
            <p className="text-gray-400">
              Total Income
            </p>

            <h3 className="text-2xl font-bold text-white">
              ₹{totalIncome}
            </h3>
          </div>
        </div>

        {/* Expense */}
        <div className="bg-slate-700 rounded-lg p-5 flex items-center gap-4">
          <FaArrowUp className="text-red-400 text-3xl"/>

          <div>
            <p className="text-gray-400">
              Total Expense
            </p>

            <h3 className="text-2xl font-bold text-white">
              ₹{totalExpense}
            </h3>
          </div>
        </div>

        {/* Savings */}
        <div className="bg-slate-700 rounded-lg p-5 flex items-center gap-4">
          <FaPiggyBank className="text-yellow-400 text-3xl"/>

          <div>
            <p className="text-gray-400">
              Total Savings
            </p>

            <h3 className="text-2xl font-bold text-white">
              ₹{totalSavings}
            </h3>
          </div>
        </div>

        {/* Highest Expense */}
        <div className="bg-slate-700 rounded-lg p-5 flex items-center gap-4">
          <FaChartPie className="text-purple-400 text-3xl"/>

          <div>
            <p className="text-gray-400">
              Highest Expense Category
            </p>

            <h3 className="text-2xl font-bold text-white">
              {highestCategory}
            </h3>
          </div>
        </div>

      </div>

      {/* Transactions */}

      <div className="mt-6 bg-slate-700 rounded-lg p-5 flex items-center">

        <FaWallet className="text-blue-400 text-3xl mr-4"/>

        <div>
          <p className="text-gray-400">
            Total Transactions
          </p>

          <h3 className="text-2xl font-bold text-white">
            {totalTransactions}
          </h3>
        </div>

      </div>

    </div>
  );
};

export default MonthlySummary;